const body = $('Admin Event Registrations Webhook').first().json.body || {};
const filters = body.filters || body.data?.filters || {};
const keyword = String(filters.keyword || filters.lineName || '').trim().toLowerCase();
const statusFilter = String(filters.status || '').trim();
const startDate = String(filters.startDate || '').trim();
const endDate = String(filters.endDate || '').trim();

function textFromValue(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(textFromValue).filter(Boolean).join(',');
  if (value.name) return String(value.name);
  if (value.plain_text) return String(value.plain_text);
  if (value.title) return textFromValue(value.title);
  if (value.rich_text) return textFromValue(value.rich_text);
  if (value.select) return textFromValue(value.select);
  if (value.date) return value.date.start || '';
  if (value.number != null) return String(value.number);
  if (value.phone_number) return String(value.phone_number);
  if (value.checkbox != null) return String(value.checkbox);
  if (value.relation) return value.relation.map((entry) => entry.id).join(',');
  return '';
}

function prop(json, names) {
  const wanted = Array.isArray(names) ? names : [names];
  for (const name of wanted) {
    if (json[name] != null) return textFromValue(json[name]).trim();
    const prefixed = json['property_' + name];
    if (prefixed != null) return textFromValue(prefixed).trim();
    const p = json.properties?.[name];
    if (p != null) return textFromValue(p).trim();
  }
  const props = json.properties || {};
  for (const [key, value] of Object.entries(props)) {
    if (wanted.some((name) => key.trim() === name || key.includes(name))) return textFromValue(value).trim();
  }
  return '';
}

const data = items.map((item) => {
  const json = item.json;
  return {
    id: json.id,
    registrationId: prop(json, ['????', '????']),
    eventId: prop(json, ['??ID']),
    eventTitle: prop(json, ['????']),
    community: prop(json, ['????']),
    name: prop(json, ['??']),
    phone: prop(json, ['??']),
    companions: Number(prop(json, ['????']) || 0),
    note: prop(json, ['??']),
    lineUserId: prop(json, ['LINE User ID']),
    lineDisplayName: prop(json, ['LINE??', 'LINE ??']),
    status: prop(json, ['??']) || 'registered',
    isDuplicate: prop(json, ['????']) === 'true',
    createdAt: prop(json, ['????']) || json.created_time || ''
  };
}).filter((item) => {
  const searchable = [item.registrationId, item.name, item.phone, item.lineDisplayName, item.lineUserId].join(' ').toLowerCase();
  const createdAt = String(item.createdAt || '');
  return (!keyword || searchable.includes(keyword))
    && (!statusFilter || item.status === statusFilter)
    && (!startDate || createdAt >= startDate)
    && (!endDate || createdAt <= endDate);
}).sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));

return [{ json: { ok: true, data } }];

const body = $('Admin Event Registrations Webhook').first().json.body || {};
const data = body.data || {};
const id = String(data.id || '').trim();
const status = String(data.status || '').trim();
if (!id) return [{ json: { ok: false, statusCode: 400, message: '???? ID' } }];
if (!['registered', 'confirmed', 'cancelled'].includes(status)) {
  return [{ json: { ok: false, statusCode: 400, message: '??????' } }];
}
return [{ json: { ok: true, pageId: id, status } }];
